select jsonb_build_object(
 'tables', (select jsonb_build_object('n', count(*), 'md5', md5(string_agg(c.relname, ',' order by c.relname))) from pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind = 'r'),
 'columns', (select jsonb_build_object('n', count(*), 'md5', md5(string_agg(c.relname || '.' || a.attname || ':' || format_type(a.atttypid, a.atttypmod) || ':' || a.attnotnull || ':' || coalesce(pg_get_expr(d.adbin, d.adrelid), '') || ':' || a.attidentity::text, '|' order by c.relname, a.attname)))
    from pg_attribute a join pg_class c on c.oid = a.attrelid left join pg_attrdef d on d.adrelid = a.attrelid and d.adnum = a.attnum where c.relnamespace = 'public'::regnamespace and c.relkind = 'r' and a.attnum > 0 and not a.attisdropped),
 'constraints', (select jsonb_build_object('n', count(*), 'md5', md5(string_agg(c.relname || '.' || k.conname || ':' || pg_get_constraintdef(k.oid), '|' order by c.relname, k.conname))) from pg_constraint k join pg_class c on c.oid = k.conrelid where c.relnamespace = 'public'::regnamespace),
 'indexes', (select jsonb_build_object('n', count(*), 'md5', md5(string_agg(indexdef, '|' order by indexname))) from pg_indexes where schemaname = 'public'),
 'functions', (select jsonb_build_object('n', count(*), 'md5', md5(string_agg(p.proname || '(' || pg_get_function_identity_arguments(p.oid) || '):' || md5(p.prosrc) || ':' || p.prosecdef || ':' || p.provolatile::text || ':' || coalesce(array_to_string(p.proconfig, ','), '') || ':' || pg_get_function_result(p.oid), '|' order by p.proname, pg_get_function_identity_arguments(p.oid)))) from pg_proc p where p.pronamespace = 'public'::regnamespace),
 'views', (select jsonb_build_object('n', count(*), 'md5', md5(string_agg(c.relname || ':' || pg_get_viewdef(c.oid, true) || ':' || coalesce(array_to_string(c.reloptions, ','), ''), '|' order by c.relname))) from pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind = 'v'),
 'triggers', (select jsonb_build_object('n', count(*), 'md5', md5(string_agg(n.nspname || '.' || c.relname || ':' || pg_get_triggerdef(t.oid, true) || ':' || t.tgenabled::text, '|' order by n.nspname, c.relname, t.tgname))) from pg_trigger t join pg_class c on c.oid = t.tgrelid join pg_namespace n on n.oid = c.relnamespace join pg_proc f on f.oid = t.tgfoid where not t.tgisinternal and f.pronamespace = 'public'::regnamespace),
 'policies', (select jsonb_build_object('n', count(*), 'md5', md5(string_agg(tablename || ':' || policyname || ':' || permissive || ':' || array_to_string(roles, ',') || ':' || cmd || ':' || coalesce(qual, '') || ':' || coalesce(with_check, ''), '|' order by tablename, policyname))) from pg_policies where schemaname = 'public'),
 'rls', (select jsonb_build_object('n', count(*) filter (where c.relrowsecurity), 'off', coalesce(jsonb_agg(c.relname order by c.relname) filter (where not c.relrowsecurity), '[]')) from pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind = 'r'),
 'sequences', (select jsonb_build_object('n', count(*), 'md5', md5(string_agg(c.relname, ',' order by c.relname))) from pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind = 'S'),
 'function_acl', (select jsonb_build_object('n', count(*), 'md5', md5(string_agg(x, '|' order by x))) from (select p.proname || '(' || pg_get_function_identity_arguments(p.oid) || ')>' || case when a.grantee = 0 then 'PUBLIC' else a.grantee::regrole::text end || ':' || a.privilege_type as x from pg_proc p, lateral aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a where p.pronamespace = 'public'::regnamespace and (a.grantee = 0 or a.grantee::regrole::text in ('anon', 'authenticated', 'service_role'))) q),
 'relation_acl', (select jsonb_build_object('n', count(*), 'md5', md5(string_agg(x, '|' order by x))) from (select c.relname || '>' || case when a.grantee = 0 then 'PUBLIC' else a.grantee::regrole::text end || ':' || a.privilege_type as x from pg_class c, lateral aclexplode(coalesce(c.relacl, acldefault(case when c.relkind = 'S' then 's'::"char" else 'r'::"char" end, c.relowner))) a where c.relnamespace = 'public'::regnamespace and c.relkind in ('r', 'v', 'S') and (a.grantee = 0 or a.grantee::regrole::text in ('anon', 'authenticated', 'service_role'))) q)
) as fp;
